mapper.select:
SELECT id, batch_id, pallet_no, tray_status, virtual_id, load_status, load_time,
       send_destination_code, send_status, send_time, invalid_flag, created_at
FROM dbo.produce_pallet
WHERE id        = #{palletId}
  AND virtual_id = #{virtualId}
  AND invalid_flag = '0'

SELECT TOP 1 p.id, p.batch_id, p.pallet_no, p.tray_status, p.virtual_id, p.load_status, p.load_time, p.send_destination_code, p.send_status, p.send_time, p.invalid_flag, p.created_at FROM dbo.produce_pallet p INNER JOIN dbo.produce_goods g ON g.pallet_id = p.id AND g.invalid_flag = '0' WHERE p.batch_id = #{batchId} AND p.virtual_id IS NULL AND p.invalid_flag = '0' AND g.uid IN
#{uid}
ORDER BY p.id ASC
